// 3. Create Top Malware Chart (Line)
const topMalwareCtx = document.getElementById('topMalwareChart');
if (topMalwareCtx) {
    // Get CSS variables for theme-aware colors
    const chartLegendColor = getComputedStyle(document.documentElement).getPropertyValue('--chart-legend-text').trim();
    const chartAxesColor = getComputedStyle(document.documentElement).getPropertyValue('--chart-axes-text').trim();
    const chartGridColor = getComputedStyle(document.documentElement).getPropertyValue('--chart-grid-line').trim();

    new Chart(topMalwareCtx, {
        type: 'line',
        data: {
            labels: ['Week 1', 'Week 2', 'Week 3', 'Week 4', 'Week 5'],
            datasets: [
                {
                    label: 'Zeus',
                    data: [120, 150, 130, 180, 160],
                    borderColor: '#e74c3c',
                    backgroundColor: '#e74c3c20',
                    fill: true,
                    tension: 0.4
                },
                {
                    label: 'WannaCry',
                    data: [80, 90, 110, 100, 130],
                    borderColor: '#007bff',
                    backgroundColor: '#007bff20',
                    fill: true,
                    tension: 0.4
                },
                {
                    label: 'Emotet',
                    data: [50, 60, 80, 70, 90],
                    borderColor: '#f1c40f',
                    backgroundColor: '#f1c40f20',
                    fill: true,
                    tension: 0.4
                }
            ]
        },
        options: {
            responsive: true,
            plugins: {
                legend: {
                    labels: {
                        color: chartLegendColor
                    }
                }
            },
            scales: {
                x: {
                    ticks: { color: chartAxesColor },
                    grid: { color: chartGridColor + '50' }
                },
                y: {
                    ticks: { color: chartAxesColor },
                    grid: { color: chartGridColor }
                }
            }
        }
    });
}

// 2. Create Malware Types Chart (Doughnut)
