                data: [65, 15, 8, 7, 5],
                backgroundColor: [
                    '#007bff', // Blue
                    '#f1c40f', // Yellow
                    '#e74c3c', // Red
                    '#9b59b6', // Purple
                    '#34495e'  // Gray
                ],
                borderColor: '#2a2a2e',
                borderWidth: 3,
            }]
        },
        options: {
            responsive: true,
            plugins: {
                legend: {
                    position: 'right',
                    labels: {
                        color: chartLegendColor,
                        boxWidth: 20
                    }
                }
            }
        }
    });
}

